import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

_cpp_decl = r"""
torch::Tensor triplet_margin_forward(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, double margin);
"""

_cuda_src = r"""
#include <torch/extension.h>
#include <ATen/cuda/CUDAContext.h>
#include <cuda_runtime.h>

__device__ __forceinline__ void warp_reduce2(float &a, float &b) {
    for (int offset = 16; offset > 0; offset >>= 1) {
        a += __shfl_down_sync(0xffffffffu, a, offset);
        b += __shfl_down_sync(0xffffffffu, b, offset);
    }
}

__global__ void triplet_margin_mean_kernel(
    const float* __restrict__ anchor,
    const float* __restrict__ positive,
    const float* __restrict__ negative,
    float* __restrict__ out,
    double* __restrict__ g_sum,
    unsigned int* __restrict__ g_cnt,
    float margin,
    float eps,
    int D,
    long long B
) {
    __shared__ float shp[8];
    __shared__ float shn[8];
    const int lane = threadIdx.x & 31;
    const int warp = threadIdx.x >> 5;
    double acc = 0.0;
    for (long long i = (long long)blockIdx.x; i < B; i += (long long)gridDim.x) {
        const long long base = i * (long long)D;
        const float* a = anchor + base;
        const float* p = positive + base;
        const float* n = negative + base;
        float sp = 0.0f;
        float sn = 0.0f;
        if ((D & 3) == 0) {
            const float4* a4 = reinterpret_cast<const float4*>(a);
            const float4* p4 = reinterpret_cast<const float4*>(p);
            const float4* n4 = reinterpret_cast<const float4*>(n);
            const int nv = D >> 2;
            for (int j = threadIdx.x; j < nv; j += blockDim.x) {
                float4 av = __ldcs(a4 + j);
                float4 pv = __ldcs(p4 + j);
                float4 nv = __ldcs(n4 + j);
                float dp0 = av.x - pv.x;
                float dp1 = av.y - pv.y;
                float dp2 = av.z - pv.z;
                float dp3 = av.w - pv.w;
                float dn0 = av.x - nv.x;
                float dn1 = av.y - nv.y;
                float dn2 = av.z - nv.z;
                float dn3 = av.w - nv.w;
                sp += dp0 * dp0 + dp1 * dp1 + dp2 * dp2 + dp3 * dp3;
                sn += dn0 * dn0 + dn1 * dn1 + dn2 * dn2 + dn3 * dn3;
            }
        } else {
            for (int j = threadIdx.x; j < D; j += blockDim.x) {
                float av = __ldcs(a + j);
                float pv = __ldcs(p + j);
                float nv = __ldcs(n + j);
                float dp = av - pv;
                float dn = av - nv;
                sp += dp * dp;
                sn += dn * dn;
            }
        }
        warp_reduce2(sp, sn);
        if (lane == 0) {
            shp[warp] = sp;
            shn[warp] = sn;
        }
        __syncthreads();
        if (warp == 0) {
            float rp = (lane < 8) ? shp[lane] : 0.0f;
            float rn = (lane < 8) ? shn[lane] : 0.0f;
            warp_reduce2(rp, rn);
            if (lane == 0) {
                float dpos = fmaxf(sqrtf(fmaxf(rp, 0.0f)), eps);
                float dneg = fmaxf(sqrtf(fmaxf(rn, 0.0f)), eps);
                acc += (double)fmaxf(dpos - dneg + margin, 0.0f);
            }
        }
        __syncthreads();
    }
    if (threadIdx.x == 0) {
        atomicAdd(g_sum, acc);
        __threadfence();
        unsigned int old = atomicAdd(g_cnt, 1u);
        if (old == gridDim.x - 1u) {
            double total = atomicAdd(g_sum, 0.0);
            out[0] = (float)(total / (double)B);
        }
    }
}

torch::Tensor triplet_margin_forward(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, double margin) {
    TORCH_CHECK(anchor.is_cuda() && positive.is_cuda() && negative.is_cuda(), "inputs must be CUDA tensors");
    TORCH_CHECK(anchor.scalar_type() == torch::kFloat32 &&
                positive.scalar_type() == torch::kFloat32 &&
                negative.scalar_type() == torch::kFloat32, "inputs must be float32");
    TORCH_CHECK(anchor.sizes() == positive.sizes() && anchor.sizes() == negative.sizes(), "shape mismatch");
    TORCH_CHECK(anchor.dim() >= 1, "expected at least 1D input");

    auto a = anchor.contiguous();
    auto p = positive.contiguous();
    auto n = negative.contiguous();

    const long long B = (long long)a.size(0);
    const long long Dll = B > 0 ? (long long)(a.numel() / B) : 0;
    TORCH_CHECK(Dll <= 0x7fffffffLL, "feature dim too large");
    const int D = (int)Dll;

    auto out = torch::empty({}, a.options());
    if (B == 0) {
        return out;
    }

    auto sum = torch::empty({1}, a.options().dtype(torch::kFloat64));
    auto cnt = torch::empty({1}, a.options().dtype(torch::kInt32));

    cudaStream_t stream = at::cuda::getCurrentCUDAStream();
    C10_CUDA_CHECK(cudaMemsetAsync(sum.data_ptr(), 0, sizeof(double), stream));
    C10_CUDA_CHECK(cudaMemsetAsync(cnt.data_ptr(), 0, sizeof(int), stream));

    int dev = 0;
    C10_CUDA_CHECK(cudaGetDevice(&dev));
    cudaDeviceProp prop;
    C10_CUDA_CHECK(cudaGetDeviceProperties(&prop, dev));
    dim3 block(256);
    int blocks_per_sm = 0;
    C10_CUDA_CHECK(cudaOccupancyMaxActiveBlocksPerMultiprocessor(
        &blocks_per_sm, (const void*)triplet_margin_mean_kernel, (int)block.x, 0));
    if (blocks_per_sm < 1) blocks_per_sm = 1;
    long long grid_ll = (long long)prop.multiProcessorCount * (long long)blocks_per_sm;
    if (grid_ll > B) grid_ll = B;
    if (grid_ll < 1) grid_ll = 1;
    dim3 grid((unsigned int)grid_ll);
    triplet_margin_mean_kernel<<<grid, block, 0, stream>>>(
        a.data_ptr<float>(),
        p.data_ptr<float>(),
        n.data_ptr<float>(),
        out.data_ptr<float>(),
        sum.data_ptr<double>(),
        reinterpret_cast<unsigned int*>(cnt.data_ptr<int>()),
        (float)margin,
        1.0e-6f,
        D,
        (long long)B
    );
    C10_CUDA_CHECK(cudaGetLastError());
    return out;
}
"""

_mod = load_inline(
    name="triplet_margin_fused_cuda",
    cpp_sources=[_cpp_decl],
    cuda_sources=[_cuda_src],
    functions=["triplet_margin_forward"],
    with_cuda=True,
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    verbose=False,
)


class ModelNew(nn.Module):
    def __init__(self, margin=1.0):
        super(ModelNew, self).__init__()
        self.margin = float(margin)

    def forward(self, anchor, positive, negative):
        return _mod.triplet_margin_forward(anchor, positive, negative, self.margin)

