        shn[warp] = sn;
    }
    __syncthreads();

    if (threadIdx.x == 0) {
        float rp = (lane < 8) ? shp[lane] : 0.0f;
        float rn = (lane < 8) ? shn[lane] : 0.0f;
        warp_reduce2(rp, rn);

        float dpos = fmaxf(sqrtf(fmaxf(rp, 0.0f)), eps);
        float dneg = fmaxf(sqrtf(fmaxf(rn, 0.0f)), eps);
        float loss = fmaxf(dpos - dneg + margin, 0.0f);

        atomicAdd(g_sum, (double)loss);
        __threadfence();
        unsigned int old = atomicAdd(g_cnt, 1u);
        if (old == gridDim.x - 1u) {
            double total = atomicAdd(g_sum, 0.0);
            out[0] = (float)(total / (double)gridDim.x);
        }
    }
}

