    triplet_margin_mean_kernel<<<grid, block, 0, stream>>>(
        a.data_ptr<float>(),
        p.data_ptr<float>(),
        n.data_ptr<float>(),
        out.data_ptr<float>(),
        sum.data_ptr<double>(),
        reinterpret_cast<unsigned int*>(cnt.data_ptr<int>()),
        (float)margin,
        1.0e-6f,
        D
    );
